keyframeRules.css:
@keyframes hs-b-smoke { 
  0% { transform: translate(0px, 0px); opacity: 0.9; }
  60% { opacity: 0.5; }
  100% { transform: translate(-16px, -36px); opacity: 0; }
}

@keyframes hs-b-meteor { 
  0%, 95.6% { opacity: 0; transform: translate(0px, 0px); }
  96% { opacity: 1; transform: translate(0px, 0px); }
  97% { transform: translate(16px, 8px); }
  98% { transform: translate(32px, 16px); opacity: 0.7; }
  99%, 100% { transform: translate(48px, 24px); opacity: 0; }
}

@keyframes swipe-out-left { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%)); opacity: 0; }
}

@keyframes swipe-out-right { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%)); opacity: 0; }
}

@keyframes swipe-out-up { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%)); opacity: 0; }
}

@keyframes swipe-out-down { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%)); opacity: 0; }
}

@keyframes sonner-fade-in { 
  0% { opacity: 0; transform: scale(0.8); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes sonner-fade-out { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}

reducedMotionRules:
@media (prefers-reduced-motion: reduce) {
  .sprite-anim { display: none !important; }
  .sprite-still { display: block !important; }
}

@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after { transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
}

@media (prefers-reduced-motion: reduce) {
  :root { scroll-behavior: auto; }
}

@media (prefers-reduced-motion) {
  .sonner-loading-bar, [data-sonner-toast], [data-sonner-toast] > * { transition: none !important; animation: auto ease 0s 1 normal none running none !important; }
}

